import { describe, expect, it } from 'vitest'
import { buildCronActivitySeries } from './activity-aggregation'

describe('cron activity across parser upgrades', () => {
  // These are fixed persisted scheduledExecutionAt values produced by 5.5.0,
  // not expectations generated by the parser being tested. Forward scheduling
  // and backward chart reconstruction must keep joining by UTC instant.
  it.each([
    {
      name: 'hourly runs across the Los Angeles spring jump',
      expression: '30 * * * *',
      timezone: 'America/Los_Angeles',
      createdAt: '2026-03-08T08:00:00.000Z',
      now: '2026-03-08T15:00:00.000Z',
      recorded: [
        '2026-03-08T08:30:00.000Z',
        '2026-03-08T09:30:00.000Z',
        '2026-03-08T10:30:00.000Z',
        '2026-03-08T11:30:00.000Z',
        '2026-03-08T12:30:00.000Z',
        '2026-03-08T13:30:00.000Z',
        '2026-03-08T14:30:00.000Z',
      ],
    },
    {
      name: 'hourly runs across the Los Angeles repeated hour',
      expression: '30 * * * *',
      timezone: 'America/Los_Angeles',
      createdAt: '2026-11-01T07:00:00.000Z',
      now: '2026-11-01T14:00:00.000Z',
      recorded: [
        '2026-11-01T07:30:00.000Z',
        '2026-11-01T08:30:00.000Z',
        '2026-11-01T09:30:00.000Z',
        '2026-11-01T10:30:00.000Z',
        '2026-11-01T11:30:00.000Z',
        '2026-11-01T12:30:00.000Z',
        '2026-11-01T13:30:00.000Z',
      ],
    },
    {
      name: 'daily runs across the Lord Howe half-hour spring jump',
      expression: '45 2 * * *',
      timezone: 'Australia/Lord_Howe',
      createdAt: '2026-10-01T00:00:00.000Z',
      now: '2026-10-06T00:00:00.000Z',
      recorded: [
        '2026-10-01T16:15:00.000Z',
        '2026-10-02T16:15:00.000Z',
        '2026-10-03T15:45:00.000Z',
        '2026-10-04T15:45:00.000Z',
        '2026-10-05T15:45:00.000Z',
      ],
    },
    {
      name: 'leap-day runs',
      expression: '0 12 29 2 *',
      timezone: 'UTC',
      createdAt: '2023-01-01T00:00:00.000Z',
      now: '2033-01-01T00:00:00.000Z',
      recorded: [
        '2024-02-29T12:00:00.000Z',
        '2028-02-29T12:00:00.000Z',
        '2032-02-29T12:00:00.000Z',
      ],
    },
    {
      name: 'month-end runs',
      expression: '0 12 L * *',
      timezone: 'UTC',
      createdAt: '2026-01-01T00:00:00.000Z',
      now: '2026-05-01T00:00:00.000Z',
      recorded: [
        '2026-01-31T12:00:00.000Z',
        '2026-02-28T12:00:00.000Z',
        '2026-03-31T12:00:00.000Z',
        '2026-04-30T12:00:00.000Z',
      ],
    },
  ])('retains recorded outcomes for $name', ({ expression, timezone, createdAt, now, recorded }) => {
    const outcomes = ['succeeded', 'failed', 'running'] as const
    const sessions = recorded.map((scheduledExecutionAt, index) => ({
      scheduledExecutionAt,
      automationStatus: outcomes[index % outcomes.length],
    }))
    const series = buildCronActivitySeries({
      task: { id: 'pre-upgrade-task', scheduleExpression: expression, timezone, createdAt: new Date(createdAt) },
      sessions,
      now: new Date(now),
      slots: recorded.length,
    })

    expect(series).toEqual(sessions.map(({ scheduledExecutionAt, automationStatus }) => ({
      scheduledAt: scheduledExecutionAt,
      status: automationStatus,
    })))
  })

  it('keeps recent recorded outcomes when an older DST slot exhausts the parser iteration limit', () => {
    // Lord Howe skips 02:00–02:29 on October 4. In 5.5.0 prev() repeated
    // an invalid shifted slot; 5.10.2 rejects that iteration instead. Its two
    // already-returned recent slots are valid and must remain visible.
    const series = buildCronActivitySeries({
      task: {
        id: 'pre-upgrade-lord-howe',
        scheduleExpression: '15 2 * * *',
        timezone: 'Australia/Lord_Howe',
        createdAt: new Date('2026-10-01T00:00:00.000Z'),
      },
      sessions: [
        { scheduledExecutionAt: '2026-10-02T15:45:00.000Z', automationStatus: 'succeeded' },
        { scheduledExecutionAt: '2026-10-04T15:15:00.000Z', automationStatus: 'succeeded' },
        { scheduledExecutionAt: '2026-10-05T15:15:00.000Z', automationStatus: 'failed' },
      ],
      now: new Date('2026-10-06T00:00:00.000Z'),
      slots: 5,
    })

    // No fabricated missing slot or outcome is added beyond the failure.
    expect(series).toEqual([
      { scheduledAt: '2026-10-04T15:15:00.000Z', status: 'succeeded' },
      { scheduledAt: '2026-10-05T15:15:00.000Z', status: 'failed' },
    ])
  })

  it.each(['not cron', '0 0 31 2 *'])('keeps a chart empty when %s cannot yield a first slot', (expression) => {
    expect(buildCronActivitySeries({
      task: {
        id: 'invalid-history',
        scheduleExpression: expression,
        timezone: 'UTC',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
      },
      sessions: [{ scheduledExecutionAt: '2026-07-09T10:00:00.000Z', automationStatus: 'succeeded' }],
      now: new Date('2026-07-10T00:00:00.000Z'),
      slots: 5,
    })).toEqual([])
  })
})
